param(
    [switch]$SkipCheck
)

$ErrorActionPreference = "Stop"
$Host.UI.RawUI.WindowTitle = "Hogwarts V1 Complete Rework"

Write-Host ""
Write-Host "============================================================" -ForegroundColor DarkYellow
Write-Host " HOGWARTS ONLINE - REWORK V1 COMPLETO" -ForegroundColor Yellow
Write-Host " Segurança + Core + Gameplay + Vida + PC + Mobile + UX" -ForegroundColor Gray
Write-Host "============================================================" -ForegroundColor DarkYellow
Write-Host ""

$required = @("server.js", "HogwartsCore.js", "index.html", "package.json")
foreach ($f in $required) {
    if (!(Test-Path (Join-Path (Get-Location) $f))) {
        throw "Execute este arquivo na raiz do projeto. Faltou: $f"
    }
}

if (-not (Get-Command node -ErrorAction SilentlyContinue)) {
    throw "Node.js nao foi encontrado no PATH."
}

$patcherPath = Join-Path (Get-Location) ".hogwarts-v1-patcher.js"

$patcher = @'
'use strict';

const fs = require('fs');
const path = require('path');

const ROOT = process.cwd();
const REQUIRED = ['server.js', 'HogwartsCore.js', 'index.html', 'package.json'];

for (const f of REQUIRED) {
  if (!fs.existsSync(path.join(ROOT, f))) {
    console.error(`❌ Execute este patch na raiz do projeto. Faltou: ${f}`);
    process.exit(2);
  }
}

const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const backupDir = path.join(ROOT, `.hogwarts-v1-backup-${stamp}`);
fs.mkdirSync(backupDir, { recursive: true });

for (const f of REQUIRED) {
  fs.copyFileSync(path.join(ROOT, f), path.join(backupDir, f));
}

function writeB64(rel, data) {
  const dest = path.join(ROOT, rel);
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.writeFileSync(dest, Buffer.from(data, 'base64'));
}

const GENERATED = {"v1/server-runtime.js": "", "v1/content.js": "", "v1-client.js": "", "v1.css": "", "scripts/check-v1.js": "", ".env.example": "", "V1_REWORK.md": ""};
for (const [rel, data] of Object.entries(GENERATED)) writeB64(rel, data);

function read(rel) { return fs.readFileSync(path.join(ROOT, rel), 'utf8'); }
function write(rel, txt) { fs.writeFileSync(path.join(ROOT, rel), txt, 'utf8'); }

function findMatchingBrace(code, open) {
  let depth = 0, mode = 'code', esc = false;
  for (let i = open; i < code.length; i++) {
    const ch = code[i], nx = code[i + 1];

    if (mode === 'line') { if (ch === '\n') mode = 'code'; continue; }
    if (mode === 'block') { if (ch === '*' && nx === '/') { mode = 'code'; i++; } continue; }

    if (mode === 'single' || mode === 'double' || mode === 'template') {
      if (esc) { esc = false; continue; }
      if (ch === '\\') { esc = true; continue; }
      if (mode === 'single' && ch === "'") mode = 'code';
      else if (mode === 'double' && ch === '"') mode = 'code';
      else if (mode === 'template' && ch === '`') mode = 'code';
      continue;
    }

    if (ch === '/' && nx === '/') { mode = 'line'; i++; continue; }
    if (ch === '/' && nx === '*') { mode = 'block'; i++; continue; }
    if (ch === "'") { mode = 'single'; continue; }
    if (ch === '"') { mode = 'double'; continue; }
    if (ch === '`') { mode = 'template'; continue; }

    if (ch === '{') depth++;
    else if (ch === '}') {
      depth--;
      if (depth === 0) return i;
    }
  }
  return -1;
}

function findBlockAt(code, start) {
  const open = code.indexOf('{', start);
  if (open < 0) return null;
  const close = findMatchingBrace(code, open);
  if (close < 0) return null;
  let end = close + 1;
  while (/\s/.test(code[end] || '')) end++;
  if (code.slice(end, end + 2) === ');') end += 2;
  else if (code[end] === ';') end++;
  return { start, open, close, end };
}

function occurrences(code, needle) {
  const out = [];
  let at = 0;
  while ((at = code.indexOf(needle, at)) >= 0) { out.push(at); at += needle.length; }
  return out;
}

function removeEarlierEventDuplicates(code, eventName) {
  const variants = [`socket.on('${eventName}'`, `socket.on("${eventName}"`, `socket.on(\`${eventName}\``];
  let positions = variants.flatMap(v => occurrences(code, v)).sort((a,b) => a-b);
  while (positions.length > 1) {
    const block = findBlockAt(code, positions[0]);
    if (!block) break;
    code = code.slice(0, block.start) + `\n// [V1] handler duplicado ${eventName} removido\n` + code.slice(block.end);
    positions = variants.flatMap(v => occurrences(code, v)).sort((a,b) => a-b);
  }
  return code;
}

function removeEarlierFunctionDuplicate(code, signatureNeedle) {
  let positions = occurrences(code, signatureNeedle);
  while (positions.length > 1) {
    const block = findBlockAt(code, positions[0]);
    if (!block) break;
    code = code.slice(0, block.start) + `\n// [V1] função duplicada removida: ${signatureNeedle}\n` + code.slice(block.end);
    positions = occurrences(code, signatureNeedle);
  }
  return code;
}

function replaceInsideMethod(code, methodName, transform) {
  const re = new RegExp(`(?:async\\s+)?${methodName.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')}\\s*\\(`);
  const m = re.exec(code);
  if (!m) return code;
  const block = findBlockAt(code, m.index);
  if (!block) return code;
  const before = code.slice(0, block.start);
  const body = code.slice(block.start, block.end);
  const after = code.slice(block.end);
  return before + transform(body) + after;
}

// -----------------------------------------------------------------------------
// server.js
// -----------------------------------------------------------------------------
let server = read('server.js');

server = server.replace(
  /const io = new Server\(server,\s*\{\s*cors:\s*\{\s*origin:\s*["']\*["']\s*\},\s*pingInterval:\s*25000,\s*pingTimeout:\s*60000\s*\}\);/,
  "const io = new Server(server, { pingInterval: 25000, pingTimeout: 60000 });"
);

if (!server.includes("installHogwartsV1({")) {
  const marker = 'const core = new HogwartsCore();';
  if (!server.includes(marker)) throw new Error('Não encontrei a criação de HogwartsCore em server.js');
  server = server.replace(marker, `${marker}
const { installHogwartsV1 } = require('./v1/server-runtime.js');
installHogwartsV1({ app, server, io, core, RelogioHogwarts, AstrolabioMagico });`);
}

server = server.replace(
  /const\s*\{\s*id\s*\}\s*=\s*req\.query\s*;/,
  "const id = req.playerId || req.query.id;"
);

for (const ev of ['forest_open_chest', 'aceitar_convite_grupo', 'pedir_presenca']) {
  server = removeEarlierEventDuplicates(server, ev);
}
server = removeEarlierFunctionDuplicate(server, 'async function iniciarForjaDeLivrosEmBackground');
server = removeEarlierFunctionDuplicate(server, 'function atualizarPresencaZona');

write('server.js', server);

// -----------------------------------------------------------------------------
// HogwartsCore.js
// -----------------------------------------------------------------------------
let core = read('HogwartsCore.js');

core = core.replace(/aa\.nuques\s*\+=\s*50\s*;/g, 'a.nuques += 50;');
core = core.replace(/if\s*\(\s*Math\.random\(\)\s*<\s*chance\s*\|\|\s*true\s*\)/g, 'if (Math.random() < chance)');

core = core.replace(
  /vendedor\.cofreGringotes\s*=\s*\(parseInt\(vendedor\.cofreGringotes\)\s*\|\|\s*0\)\s*\+\s*parseInt\(oferta\.preco\)\s*;/g,
  `if (typeof vendedor.cofreGringotes === 'number') vendedor.cofreGringotes = { galeoes: vendedor.cofreGringotes, siclos: 0, nuques: 0 };
            vendedor.cofreGringotes ||= { galeoes: 0, siclos: 0, nuques: 0 };
            vendedor.cofreGringotes.galeoes = (Number(vendedor.cofreGringotes.galeoes) || 0) + (Number(oferta.preco) || 0);`
);

core = core.replace(
  /if\s*\(\s*a\.cofreGringotes\s*>\s*0\s*&&\s*Math\.random\(\)\s*<\s*0\.01\s*\)\s*\{[\s\S]*?a\.cofreGringotes\s*\+=\s*rendimento\s*;\s*\}/,
  `if (a.cofreGringotes && typeof a.cofreGringotes === 'object' && a.cofreGringotes.galeoes > 0 && Math.random() < 0.00001) {
                let rendimento = Math.max(1, Math.floor(a.cofreGringotes.galeoes * 0.0005));
                a.cofreGringotes.galeoes += rendimento;
            }`
);

core = replaceInsideMethod(core, 'gerarVarinhaOllivanders', body => {
  return body
    .replace(/if\s*\(\s*a\.nuques\s*<\s*47\s*\)\s*return\s*\{\s*erro:\s*["'][^"']*["']\s*\}\s*;/,
      `if ((a.siclos || 0) < 47) return { erro: "O vínculo da varinha custa 47 Sicles." };`)
    .replace(/a\.nuques\s*\+=\s*50\s*;\s*a\.siclos\s*\+=\s*5\s*;/,
      'a.siclos -= 47;');
});

core = replaceInsideMethod(core, 'atacarWorldBossGlobal', body => {
  if (!body.includes('Foco insuficiente para atacar o Boss')) {
    body = body.replace(
      /a\.focoAtual\s*-=\s*2\s*;/,
      `if (a.focoAtual < 2) return { erro: "Foco insuficiente para atacar o Boss." };
        a.focoAtual -= 2;`
    );
  }
  return body;
});

core = replaceInsideMethod(core, 'processarAcaoPvP', body =>
  body.replace(/let\s+duracaoMs\s*=\s*1200\s*;/g, "let duracaoMs = ((f && f.duracao) || 1.2) * 1000;")
);

core = replaceInsideMethod(core, 'processarActionCombat', body =>
  body.replace(/let\s+duracaoMs\s*=\s*1200\s*;/g, "let duracaoMs = (feitico.duracao || 1.2) * 1000;")
);

core = core.replace(
  /async\s+criarFeiticoInedito\s*\(\s*aluno\s*,\s*tese\s*\)\s*\{\s*return\s+null\s*;\s*\}/,
`async criarFeiticoInedito(aluno, tese) {
        if (!this.apiKey || !this.groq) return null;
        try {
            const prompt = \`Crie um feitiço ORIGINAL e equilibrado para um RPG escolar de magia.
Bruxo: \${aluno.nome}, nível \${aluno.nivel}.
Tese do jogador: \${String(tese).slice(0, 1400)}
Retorne APENAS JSON:
{"nome":"Nome","tipoMecanica":"ataque|status|cura|escudo","elemento":"fogo|agua|gelo|eletrico|vento|cinetico|luz|trevas|terra","custoFocoBase":1,"poderBase":50,"efeitoSecundario":null,"duracao":2,"lore":"texto"}
Limites: custo 2-8, poder 0-180, duração 0-5. Nenhum efeito de morte instantânea, moeda, XP ou alteração permanente.\`;
            const res = await this.groq.chat.completions.create({
                messages: [{ role: "user", content: prompt }],
                model: "llama-3.1-8b-instant",
                response_format: { type: "json_object" }
            });
            const f = this._extrairJSONBlindado(res.choices[0].message.content);
            if (!f || !f.nome) return null;
            f.custoFocoBase = Math.max(2, Math.min(8, Number(f.custoFocoBase) || 3));
            f.poderBase = Math.max(0, Math.min(180, Number(f.poderBase) || 40));
            f.duracao = Math.max(0, Math.min(5, Number(f.duracao) || 0));
            f.lore = String(f.lore || "Magia criada por pesquisa independente.").slice(0, 500);
            return f;
        } catch (e) {
            return null;
        }
    }`
);

write('HogwartsCore.js', core);

// -----------------------------------------------------------------------------
// index.html
// -----------------------------------------------------------------------------
let index = read('index.html');

if (!index.includes('/v1.css')) {
  index = index.replace(/<\/head>/i, '    <link rel="stylesheet" href="/v1.css">\\n</head>');
}
if (!index.includes('/v1-client.js')) {
  index = index.replace(/<\/body>/i, '    <script src="/v1-client.js"></script>\\n</body>');
}

for (const fn of ['gerirTelasPorEstado', 'atualizarPosicaoMira', 'dispararMira', 'criarOndaDeChoqueVisual']) {
  index = removeEarlierFunctionDuplicate(index, `function ${fn}`);
}
for (const ev of ['mmo_raid_status', 'mmo_combat_update', 'receber_convite_grupo', 'mmo_jogador_saiu']) {
  index = removeEarlierEventDuplicates(index, ev);
}

index = index.replace(/toast\.innerHTML\s*=\s*msg\s*;/g, 'toast.textContent = String(msg ?? "");');

index = index.replace(
  /box\.innerHTML\s*\+=\s*`<div class="chat-msg"><span style="color:\$\{corNome\}; font-weight:bold;">\$\{dados\.autor\}:<\/span> <span style="color:#d0d5dc;">\$\{dados\.texto\}<\/span><\/div>`\s*;/,
  `{
            const row = document.createElement('div');
            row.className = 'chat-msg';
            const who = document.createElement('span');
            who.style.color = corNome;
            who.style.fontWeight = 'bold';
            who.textContent = String(dados.autor || 'Sistema') + ': ';
            const message = document.createElement('span');
            message.style.color = '#d0d5dc';
            message.textContent = String(dados.texto || '');
            row.append(who, message);
            box.appendChild(row);
        }`
);

write('index.html', index);

// -----------------------------------------------------------------------------
// package.json
// -----------------------------------------------------------------------------
const pkg = JSON.parse(read('package.json'));
pkg.scripts ||= {};
pkg.scripts.start = 'node server.js';
pkg.scripts.check = 'node scripts/check-v1.js';
pkg.scripts.test = 'npm run check';
write('package.json', JSON.stringify(pkg, null, 2) + '\\n');

// -----------------------------------------------------------------------------
// Rollback
// -----------------------------------------------------------------------------
const rollback = `param()
$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $MyInvocation.MyCommand.Path
$backup = Join-Path $root "${path.basename(backupDir)}"
if (!(Test-Path $backup)) { throw "Backup não encontrado: $backup" }
Copy-Item (Join-Path $backup "server.js") (Join-Path $root "server.js") -Force
Copy-Item (Join-Path $backup "HogwartsCore.js") (Join-Path $root "HogwartsCore.js") -Force
Copy-Item (Join-Path $backup "index.html") (Join-Path $root "index.html") -Force
Copy-Item (Join-Path $backup "package.json") (Join-Path $root "package.json") -Force
Write-Host "Rollback dos arquivos principais concluído." -ForegroundColor Yellow
`;
fs.writeFileSync(path.join(ROOT, 'ROLLBACK_HOGWARTS_V1.ps1'), rollback, 'utf8');

console.log(`✅ Backup: ${backupDir}`);
console.log('✅ Hogwarts V1 aplicado.');
console.log('➡️ Próximo comando: npm run check');

'@

Set-Content -Path $patcherPath -Value $patcher -Encoding UTF8

try {
    Write-Host "[1/3] Aplicando rework integrado..." -ForegroundColor Cyan
    node $patcherPath
    if ($LASTEXITCODE -ne 0) { throw "O patcher retornou codigo $LASTEXITCODE" }

    Write-Host "[2/3] Verificando sintaxe..." -ForegroundColor Cyan
    node --check server.js
    if ($LASTEXITCODE -ne 0) { throw "server.js ficou com erro de sintaxe" }
    node --check HogwartsCore.js
    if ($LASTEXITCODE -ne 0) { throw "HogwartsCore.js ficou com erro de sintaxe" }
    node --check v1/server-runtime.js
    if ($LASTEXITCODE -ne 0) { throw "v1/server-runtime.js ficou com erro de sintaxe" }

    if (-not $SkipCheck) {
        Write-Host "[3/3] Rodando smoke-check V1..." -ForegroundColor Cyan
        npm run check
        if ($LASTEXITCODE -ne 0) {
            Write-Host ""
            Write-Host "O patch foi aplicado, mas o smoke-check encontrou algo para revisar." -ForegroundColor Yellow
            Write-Host "Use ROLLBACK_HOGWARTS_V1.ps1 se quiser reverter os arquivos principais." -ForegroundColor Yellow
            exit 1
        }
    }

    Write-Host ""
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host " HOGWARTS V1 REWORK APLICADO COM SUCESSO" -ForegroundColor Green
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host ""
    Write-Host "Agora:" -ForegroundColor White
    Write-Host "  1. Configure SESSION_SECRET no .env" -ForegroundColor Gray
    Write-Host "  2. Configure ADMIN_PLAYER_ID no .env" -ForegroundColor Gray
    Write-Host "  3. npm install" -ForegroundColor Gray
    Write-Host "  4. npm start" -ForegroundColor Gray
    Write-Host ""
    Write-Host "Leia V1_REWORK.md para o resumo completo." -ForegroundColor DarkGray
}
finally {
    if (Test-Path $patcherPath) {
        Remove-Item $patcherPath -Force -ErrorAction SilentlyContinue
    }
}
